import json,os,sys
m=json.load(open("hunsu.json")); l=json.load(open("hunsu.lock.json"))
assert m["roles"]==l["roles"]==l["roles-declared"], "roles: manifest and lock differ"
assert m["reporters"]==l["reporters"], "reporters: manifest and lock differ"
for n,p in m["plugins"].items(): assert l["plugins"][n]["version"]==p["version"], n
bad=[]
for k in ("reviewer","coherence"):
  if m["roles"][k][-2:]!=["--target","."]: bad.append("role "+k+": not --target .")
for k,v in m["reporters"].items():
  if v[-2:]!=["--target","."]: bad.append("reporter "+k+": not --target .")
for kind,allowed,table in (("role",{"{request}","{response}"},m["roles"]),("reporter",{"{since}"},m["reporters"])):
  for k,v in table.items():
    if v=="session": continue
    for a in v:
      if "{" in a and not a.startswith("{plugin") and a not in allowed: bad.append(kind+" "+k+": placeholder "+a)
for f in sys.argv[1:]:
  ver=os.path.basename(os.path.dirname(f)); name=os.path.basename(os.path.dirname(os.path.dirname(f)))
  if not os.path.isfile(f) or l["plugins"].get(name,{}).get("version")!=ver: bad.append("not the locked release: "+f)
assert not bad, bad
print("roles+reporters equal in manifest and lock; reviewer/coherence/reporters --target .; placeholders only {request} {response} {since}; engines resolve to locked releases:", *sys.argv[1:])

